        }
        assertEquals(binaryIsNull[i], tsBlock.getColumn(5).isNull(i));
        if (!binaryIsNull[i]) {
            assertEquals(binaryValueArray[i], tsBlock.getColumn(5).getBinary(i));
        }
    }
