@Test
public void testInsertIntoSortedDeletions() {
    ChunkMetadata chunkMetadata = new ChunkMetadata();
    // add into empty list
    chunkMetadata.insertIntoSortedDeletions(new TimeRange(6, 27));
    Assert.assertArrayEquals(new TimeRange[] { new TimeRange(6, 27) }, chunkMetadata.getDeleteIntervalList().toArray(new TimeRange[0]));
    // add not overlap
    chunkMetadata.insertIntoSortedDeletions(new TimeRange(61, 69));
    Assert.assertArrayEquals(new TimeRange[] { new TimeRange(6, 27), new TimeRange(61, 69) }, chunkMetadata.getDeleteIntervalList().toArray(new TimeRange[0]));
    // add left overlap
    chunkMetadata.insertIntoSortedDeletions(new TimeRange(0, 19));
    Assert.assertArrayEquals(new TimeRange[] { new TimeRange(0, 27), new TimeRange(61, 69) }, chunkMetadata.getDeleteIntervalList().toArray(new TimeRange[0]));
    chunkMetadata.insertIntoSortedDeletions(new TimeRange(59, 60));
    Assert.assertArrayEquals(new TimeRange[] { new TimeRange(0, 27), new TimeRange(59, 60), new TimeRange(61, 69) }, chunkMetadata.getDeleteIntervalList().toArray(new TimeRange[0]));
    // add right overlap
    chunkMetadata.insertIntoSortedDeletions(new TimeRange(27, 30));
    Assert.assertArrayEquals(new TimeRange[] { new TimeRange(0, 30), new TimeRange(59, 60), new TimeRange(61, 69) }, chunkMetadata.getDeleteIntervalList().toArray(new TimeRange[0]));
    chunkMetadata.insertIntoSortedDeletions(new TimeRange(65, 70));
    Assert.assertArrayEquals(new TimeRange[] { new TimeRange(0, 30), new TimeRange(59, 60), new TimeRange(61, 70) }, chunkMetadata.getDeleteIntervalList().toArray(new TimeRange[0]));
    // add internal
    chunkMetadata.insertIntoSortedDeletions(new TimeRange(40, 50));
    Assert.assertArrayEquals(new TimeRange[] { new TimeRange(0, 30), new TimeRange(40, 50), new TimeRange(59, 60), new TimeRange(61, 70) }, chunkMetadata.getDeleteIntervalList().toArray(new TimeRange[0]));
    chunkMetadata.insertIntoSortedDeletions(new TimeRange(30, 40));
    Assert.assertArrayEquals(new TimeRange[] { new TimeRange(0, 50), new TimeRange(59, 60), new TimeRange(61, 70) }, chunkMetadata.getDeleteIntervalList().toArray(new TimeRange[0]));
}

