    Assert.assertEquals(4, dictionaryColumn.getLong(0));
    Assert.assertEquals(3, dictionaryColumn.getLong(1));
    Assert.assertEquals(0, dictionaryColumn.getLong(2));
    Assert.assertEquals(3, dictionaryColumn.getLong(3));
