@Test
public void testOneTimeAndSeries() {
    Filter filter1 = FilterFactory.or(ValueFilterApi.gt(DEFAULT_MEASUREMENT_INDEX, 100L, TSDataType.INT64), ValueFilterApi.lt(DEFAULT_MEASUREMENT_INDEX, 50L, TSDataType.INT64));
    SingleSeriesExpression singleSeriesExp1 = new SingleSeriesExpression(new Path("d2", "s1", true), filter1);
    Filter filter2 = FilterFactory.or(ValueFilterApi.gt(DEFAULT_MEASUREMENT_INDEX, 100.5f, TSDataType.FLOAT), ValueFilterApi.lt(DEFAULT_MEASUREMENT_INDEX, 50.6f, TSDataType.FLOAT));
    SingleSeriesExpression singleSeriesExp2 = new SingleSeriesExpression(new Path("d1", "s2", true), filter2);
    Filter timeFilter = TimeFilterApi.lt(14001234L);
    IExpression globalTimeFilter = new GlobalTimeExpression(timeFilter);
    IExpression expression = BinaryExpression.and(BinaryExpression.or(singleSeriesExp1, singleSeriesExp2), globalTimeFilter);
    try {
        String rightRet = "[[d2.s1:((measurements[0] > 100 || measurements[0] < 50) && time < 14001234)] " + "|| [d1.s2:((measurements[0] > 100.5 || measurements[0] < 50.6) " + "&& time < 14001234)]]";
        IExpression regularFilter = expressionOptimizer.optimize(expression, selectedSeries);
        Assert.assertEquals(rightRet, regularFilter.toString());
    } catch (QueryFilterOptimizationException e) {
        Assert.fail();
    }
}

