@Test
public void testTwoTimeCombine() {
    Filter filter1 = FilterFactory.or(ValueFilterApi.gt(DEFAULT_MEASUREMENT_INDEX, 100L, TSDataType.INT64), ValueFilterApi.lt(DEFAULT_MEASUREMENT_INDEX, 50L, TSDataType.INT64));
    SingleSeriesExpression singleSeriesExp1 = new SingleSeriesExpression(new Path("d2", "s1", true), filter1);
    Filter filter2 = FilterFactory.or(ValueFilterApi.gt(DEFAULT_MEASUREMENT_INDEX, 100.5f, TSDataType.FLOAT), ValueFilterApi.lt(DEFAULT_MEASUREMENT_INDEX, 50.6f, TSDataType.FLOAT));
    SingleSeriesExpression singleSeriesExp2 = new SingleSeriesExpression(new Path("d1", "s2", true), filter2);
    IExpression globalTimeFilter1 = new GlobalTimeExpression(TimeFilterApi.lt(14001234L));
    IExpression globalTimeFilter2 = new GlobalTimeExpression(TimeFilterApi.gt(14001000L));
    IExpression expression = BinaryExpression.or(BinaryExpression.or(singleSeriesExp1, singleSeriesExp2), BinaryExpression.and(globalTimeFilter1, globalTimeFilter2));
    try {
        String rightRet = "[[[[d1.s1:(time < 14001234 && time > 14001000)] " + "|| [d2.s1:((time < 14001234 && time > 14001000) " + "|| (measurements[0] > 100 || measurements[0] < 50))]] " + "|| [d1.s2:((time < 14001234 && time > 14001000) " + "|| (measurements[0] > 100.5 || measurements[0] < 50.6))]] " + "|| [d2.s2:(time < 14001234 && time > 14001000)]]";
        IExpression regularFilter = expressionOptimizer.optimize(expression, selectedSeries);
        Assert.assertEquals(rightRet, regularFilter.toString());
    } catch (QueryFilterOptimizationException e) {
        Assert.fail();
    }
    IExpression expression2 = BinaryExpression.and(BinaryExpression.or(singleSeriesExp1, singleSeriesExp2), BinaryExpression.and(globalTimeFilter1, globalTimeFilter2));
    try {
        String rightRet2 = "[[d2.s1:((measurements[0] > 100 || measurements[0] < 50) " + "&& (time < 14001234 && time > 14001000))] || " + "[d1.s2:((measurements[0] > 100.5 || measurements[0] < 50.6) " + "&& (time < 14001234 && time > 14001000))]]";
        IExpression regularFilter2 = expressionOptimizer.optimize(expression2, selectedSeries);
        Assert.assertEquals(rightRet2, regularFilter2.toString());
    } catch (QueryFilterOptimizationException e) {
        Assert.fail();
    }
    IExpression expression3 = BinaryExpression.or(expression2, expression);
    try {
        expressionOptimizer.optimize(expression3, selectedSeries);
    } catch (QueryFilterOptimizationException e) {
        Assert.fail();
    }
}

