@Test
public void testReverse() {
    Assert.assertEquals(TimeFilterApi.gt(1), TimeFilterApi.ltEq(1).reverse());
    Assert.assertEquals(TimeFilterApi.gtEq(1), TimeFilterApi.lt(1).reverse());
    Assert.assertEquals(TimeFilterApi.lt(1), TimeFilterApi.gtEq(1).reverse());
    Assert.assertEquals(TimeFilterApi.ltEq(1), TimeFilterApi.gt(1).reverse());
    Assert.assertEquals(TimeFilterApi.eq(1), TimeFilterApi.notEq(1).reverse());
    Assert.assertEquals(TimeFilterApi.notEq(1), TimeFilterApi.eq(1).reverse());
    Assert.assertEquals(ValueFilterApi.like(DEFAULT_MEASUREMENT_INDEX, LikePattern.compile("s%", Optional.empty()), TSDataType.TEXT), ValueFilterApi.notLike(DEFAULT_MEASUREMENT_INDEX, LikePattern.compile("s%", Optional.empty()), TSDataType.TEXT).reverse());
    Assert.assertEquals(ValueFilterApi.notLike(DEFAULT_MEASUREMENT_INDEX, LikePattern.compile("s%", Optional.empty()), TSDataType.TEXT), ValueFilterApi.like(DEFAULT_MEASUREMENT_INDEX, LikePattern.compile("s%", Optional.empty()), TSDataType.TEXT).reverse());
    Assert.assertEquals(ValueFilterApi.regexp(DEFAULT_MEASUREMENT_INDEX, Pattern.compile("s*"), TSDataType.TEXT), ValueFilterApi.notRegexp(DEFAULT_MEASUREMENT_INDEX, Pattern.compile("s*"), TSDataType.TEXT).reverse());
    Assert.assertEquals(ValueFilterApi.notRegexp(DEFAULT_MEASUREMENT_INDEX, Pattern.compile("s*"), TSDataType.TEXT), ValueFilterApi.regexp(DEFAULT_MEASUREMENT_INDEX, Pattern.compile("s*"), TSDataType.TEXT).reverse());
    Assert.assertEquals(TimeFilterApi.between(1, 100), TimeFilterApi.notBetween(1, 100).reverse());
    Assert.assertEquals(TimeFilterApi.notBetween(1, 100), TimeFilterApi.between(1, 100).reverse());
    // TODO: add StringFilter test
    Assert.assertEquals(ValueFilterApi.in(DEFAULT_MEASUREMENT_INDEX, new HashSet<>(Arrays.asList(new Binary("a", TSFileConfig.STRING_CHARSET), new Binary("b", TSFileConfig.STRING_CHARSET))), TSDataType.TEXT), ValueFilterApi.notIn(DEFAULT_MEASUREMENT_INDEX, new HashSet<>(Arrays.asList(new Binary("a", TSFileConfig.STRING_CHARSET), new Binary("b", TSFileConfig.STRING_CHARSET))), TSDataType.TEXT).reverse());
    Assert.assertEquals(ValueFilterApi.in(DEFAULT_MEASUREMENT_INDEX, new HashSet<>(Arrays.asList(new Binary("a", TSFileConfig.STRING_CHARSET), new Binary("b", TSFileConfig.STRING_CHARSET))), TSDataType.TEXT), ValueFilterApi.notIn(DEFAULT_MEASUREMENT_INDEX, new HashSet<>(Arrays.asList(new Binary("a", TSFileConfig.STRING_CHARSET), new Binary("b", TSFileConfig.STRING_CHARSET))), TSDataType.TEXT).reverse());
    Assert.assertEquals(ValueFilterApi.notIn(DEFAULT_MEASUREMENT_INDEX, new HashSet<>(Arrays.asList(new Binary("a", TSFileConfig.STRING_CHARSET), new Binary("b", TSFileConfig.STRING_CHARSET))), TSDataType.TEXT), ValueFilterApi.in(DEFAULT_MEASUREMENT_INDEX, new HashSet<>(Arrays.asList(new Binary("a", TSFileConfig.STRING_CHARSET), new Binary("b", TSFileConfig.STRING_CHARSET))), TSDataType.TEXT).reverse());
    Assert.assertEquals(TimeFilterApi.gt(1), FilterFactory.not(TimeFilterApi.gt(1)).reverse());
    Assert.assertEquals(FilterFactory.and(TimeFilterApi.gt(1), TimeFilterApi.ltEq(1)), FilterFactory.or(TimeFilterApi.ltEq(1), TimeFilterApi.gt(1)).reverse());
    Assert.assertEquals(FilterFactory.or(TimeFilterApi.ltEq(1), TimeFilterApi.gt(1)), FilterFactory.and(TimeFilterApi.gt(1), TimeFilterApi.ltEq(1)).reverse());
}

@Test
public void testRemoveNot() {
    Assert.assertEquals(TimeFilterApi.ltEq(1), PredicateRemoveNotRewriter.rewrite(FilterFactory.not(TimeFilterApi.gt(1))));
    Assert.assertEquals(ValueFilterApi.regexp(DEFAULT_MEASUREMENT_INDEX, Pattern.compile("s*"), TSDataType.TEXT), PredicateRemoveNotRewriter.rewrite(FilterFactory.not(ValueFilterApi.notRegexp(DEFAULT_MEASUREMENT_INDEX, Pattern.compile("s*"), TSDataType.TEXT))));
