    Assert.assertEquals(FilterFactory.and(TimeFilterApi.gt(1), TimeFilterApi.ltEq(1)), PredicateRemoveNotRewriter.rewrite(FilterFactory.and(FilterFactory.not(TimeFilterApi.ltEq(1)), FilterFactory.not(TimeFilterApi.gt(1)))));
}

