@Test
public void readByTimestamp() throws IOException {
    CachedChunkLoaderImpl seriesChunkLoader = new CachedChunkLoaderImpl(fileReader);
    List<IChunkMetadata> chunkMetadataList = metadataQuerierByFile.getChunkMetaDataList(new Path("d1", "s1", true));
    AbstractFileSeriesReader seriesReader = new FileSeriesReader(seriesChunkLoader, chunkMetadataList, null);
    List<Long> timeList = new ArrayList<>();
    List<Object> valueList = new ArrayList<>();
    int count = 0;
    BatchData data = null;
    while (seriesReader.hasNextBatch()) {
        data = seriesReader.nextBatch();
        while (data.hasCurrent()) {
            timeList.add(data.currentTime() - 1);
            valueList.add(null);
            timeList.add(data.currentTime());
            valueList.add(data.currentValue());
            data.next();
            count++;
        }
    }
    long startTimestamp = System.currentTimeMillis();
    count = 0;
    FileSeriesReaderByTimestamp seriesReaderFromSingleFileByTimestamp = new FileSeriesReaderByTimestamp(seriesChunkLoader, chunkMetadataList);
    for (long time : timeList) {
        Object value = seriesReaderFromSingleFileByTimestamp.getValueInTimestamp(time);
        if (value == null) {
            Assert.assertNull(valueList.get(count));
        } else {
            Assert.assertEquals(valueList.get(count), value);
        }
        count++;
    }
    long endTimestamp = System.currentTimeMillis();
    System.out.println("SeriesReadWithFilterTest. [Time used]: " + (endTimestamp - startTimestamp) + " ms. [Read Count]: " + count);
}

