@Test
public void testChunkReaderWithoutStatistics() throws IOException {
    try (final TsFileSequenceReader tsFileSequenceReader = new TsFileSequenceReader(file.getPath())) {
        for (int i = 0; i < deviceNum; i++) {
            final List<AbstractAlignedChunkMetadata> chunkMetadataList = tsFileSequenceReader.getAlignedChunkMetadata(Factory.DEFAULT_FACTORY.create(testStorageGroup + PATH_SEPARATOR + "d1000" + i), true);
            for (final AbstractAlignedChunkMetadata chunkMetadata : chunkMetadataList) {
                Chunk timeChunk = tsFileSequenceReader.readMemChunk((ChunkMetadata) chunkMetadata.getTimeChunkMetadata());
                timeChunk = new Chunk(timeChunk.getHeader(), timeChunk.getData());
                final List<Chunk> valueChunkList = new ArrayList<>();
                for (final IChunkMetadata valueChunkMetadata : chunkMetadata.getValueChunkMetadataList()) {
                    final Chunk valueChunk = tsFileSequenceReader.readMemChunk((ChunkMetadata) valueChunkMetadata);
                    valueChunkList.add(new Chunk(valueChunk.getHeader(), valueChunk.getData()));
                }
                final AlignedChunkReader chunkReader = new AlignedChunkReaderWithoutStatistics(timeChunk, valueChunkList);
                Assert.assertEquals(1, chunkReader.loadPageReaderList().size());
            }
        }
    }
}

