@Test
public void testReadTsFileSequentially() throws IOException {
    TsFileSequenceReader reader = new TsFileSequenceReader(FILE_PATH);
    reader.position(TSFileConfig.MAGIC_STRING.getBytes().length + 1);
    Map<IDeviceID, List<Pair<Long, Long>>> deviceChunkGroupMetadataOffsets = new HashMap<>();
    long startOffset = reader.position();
    byte marker;
    while ((marker = reader.readMarker()) != MetaMarker.SEPARATOR) {
        switch(marker) {
            case MetaMarker.CHUNK_HEADER:
            case MetaMarker.ONLY_ONE_PAGE_CHUNK_HEADER:
                ChunkHeader header = reader.readChunkHeader(marker);
                int dataSize = header.getDataSize();
                while (dataSize > 0) {
                    PageHeader pageHeader = reader.readPageHeader(header.getDataType(), header.getChunkType() == MetaMarker.CHUNK_HEADER);
                    ByteBuffer pageData = reader.readPage(pageHeader, header.getCompressionType());
                    dataSize -= pageHeader.getSerializedPageSize();
                }
                break;
            case MetaMarker.CHUNK_GROUP_HEADER:
                ChunkGroupHeader chunkGroupHeader = reader.readChunkGroupHeader();
                long endOffset = reader.position();
                Pair<Long, Long> pair = new Pair<>(startOffset, endOffset);
                deviceChunkGroupMetadataOffsets.putIfAbsent(chunkGroupHeader.getDeviceID(), new ArrayList<>());
                List<Pair<Long, Long>> metadatas = deviceChunkGroupMetadataOffsets.get(chunkGroupHeader.getDeviceID());
                metadatas.add(pair);
                startOffset = endOffset;
                break;
            case MetaMarker.OPERATION_INDEX_RANGE:
                reader.readPlanIndex();
                break;
            default:
                MetaMarker.handleUnexpectedMarker(marker);
        }
    }
    reader.close();
}

