@Test
public void calculateIntervalTest() {
    // 1mo duration after 2023-01-31
    long result = calcPositiveIntervalByMonth(Timestamp.valueOf("2023-01-31 00:00:00").getTime(), new TimeDuration(1, 0), TimeZone.getDefault(), TimeUnit.MILLISECONDS);
    Assert.assertEquals(Timestamp.valueOf("2023-02-28 00:00:00").getTime(), result);
    result = calcPositiveIntervalByMonth(Timestamp.valueOf("2023-02-28 00:00:00").getTime(), new TimeDuration(2, 0), TimeZone.getDefault(), TimeUnit.MILLISECONDS);
    Assert.assertEquals(Timestamp.valueOf("2023-04-28 00:00:00").getTime(), result);
    result = calcPositiveIntervalByMonth(Timestamp.valueOf("2023-01-30 00:00:00").getTime(), new TimeDuration(2, 0), TimeZone.getDefault(), TimeUnit.MILLISECONDS);
    Assert.assertEquals(Timestamp.valueOf("2023-03-30 00:00:00").getTime(), result);
    // 1mo1d duration after 2023-01-31
    result = calcPositiveIntervalByMonth(Timestamp.valueOf("2023-01-31 00:00:00").getTime(), new TimeDuration(1, 86400_000), TimeZone.getDefault(), TimeUnit.MILLISECONDS);
    Assert.assertEquals(Timestamp.valueOf("2023-03-01 00:00:00").getTime(), result);
    // 1mo1d1ns duration after 2023-01-31
    result = calcPositiveIntervalByMonth(Timestamp.valueOf("2023-01-31 00:00:00").getTime() * 1000_000, new TimeDuration(1, 86400_000_000_001L), TimeZone.getDefault(), TimeUnit.NANOSECONDS);
    Assert.assertEquals(Timestamp.valueOf("2023-03-01 00:00:00").getTime() * 1000_000 + 1, result);
}

