    try (TsFileWriter tsFileWriter = new TsFileWriter(f)) {
        registerAlignedTimeseries(tsFileWriter);
        List<IMeasurementSchema> writeMeasurementScheams = new ArrayList<>();
        // example1
        writeMeasurementScheams.add(alignedMeasurementSchemas.get(0));
        writeMeasurementScheams.add(alignedMeasurementSchemas.get(1));
        TsFileGeneratorUtils.writeWithTsRecord(tsFileWriter, deviceId, writeMeasurementScheams, 30, 0, 0, true);
        // example2
        writeMeasurementScheams.clear();
        writeMeasurementScheams.add(alignedMeasurementSchemas.get(2));
        writeMeasurementScheams.add(alignedMeasurementSchemas.get(1));
        writeMeasurementScheams.add(alignedMeasurementSchemas.get(0));
        TsFileGeneratorUtils.writeWithTsRecord(tsFileWriter, deviceId, writeMeasurementScheams, 30, 1000, 500, true);
        // example3 : late data
        writeMeasurementScheams.clear();
        writeMeasurementScheams.add(alignedMeasurementSchemas.get(2));
        TsFileGeneratorUtils.writeWithTsRecord(tsFileWriter, deviceId, writeMeasurementScheams, 60, 300000, 50, true);
    }
    TsFileReader tsFileReader = new TsFileReader(new TsFileSequenceReader(f.getAbsolutePath()));
    for (int i = 0; i < 3; i++) {
        QueryExpression queryExpression = QueryExpression.create(Collections.singletonList(new Path(deviceId, alignedMeasurementSchemas.get(i).getMeasurementName(), true)), null);
        QueryDataSet queryDataSet = tsFileReader.query(queryExpression);
