        ByteBuffer buffer = ByteBuffer.wrap(publicBAOS.getBuf(), 0, publicBAOS.size());
        // uncompressedSize
        assertEquals(67, ReadWriteForEncodingUtils.readUnsignedVarInt(buffer));
